# Fermat's Factorization in Python
import gmpy2

def fermat_factor(n):
    a = gmpy2.isqrt(n) + 1
    while True:
        b2 = a * a - n
        b, exact = gmpy2.isqrt_rem(b2)
        if exact == 0 and b * b == b2:
            return int(a - b), int(a + b)
        a += 1

